52	/** Template keys whose emails ship the itemised invoice as an attachment. */
53	const INVOICE_ATTACH_TEMPLATES = new Set(["receipt", "invoice_new", "renewal_reminder"]);
54	
55	export type MailAttachment = { filename: string; content: string | Buffer; contentType?: string };
56	
57	/**
58	 * Build the invoice attachment for an email. There is no PDF library installed
59	 * (and we can't add dependencies), so we attach the branded, print-ready
60	 * invoice HTML produced by `lib/invoices.ts` — recipients open it and use their
61	 * browser's Print → Save as PDF, matching the on-site download route.
62	 */
63	async function invoiceAttachment(invoiceId: string): Promise<MailAttachment | null> {
64	  try {
65	    const invoice = await db.invoice.findUnique({
66	      where: { id: invoiceId },
67	      include: { user: { select: { name: true, email: true } } },
68	    });
69	    if (!invoice) return null;
70	    const html = renderInvoiceHTML(invoice, invoice.user);
71	    const number = String(invoice.number).padStart(5, "0");
72	    return { filename: `nxeon-invoice-${number}.html`, content: html, contentType: "text/html; charset=utf-8" };
73	  } catch (e) {
74	    console.error("[mailer] failed to build invoice attachment:", e);
75	    return null;
76	  }
77	}
