216	/**
217	 * Render a stored (or default) template for `key`, substituting `vars`,
218	 * returning the final subject and full wrapped HTML ready to send/preview.
219	 */
220	export async function renderTemplate(key: string, vars: Record<string, unknown> = {}): Promise<RenderedEmail> {
221	  let subject: string;
222	  let body: string;
223	
224	  let row: { subject: string; html: string; enabled: boolean } | null = null;
225	  try {
226	    row = await db.emailTemplate.findUnique({
227	      where: { key },
228	      select: { subject: true, html: true, enabled: true },
229	    });
230	  } catch {
231	    row = null;
232	  }
233	
234	  if (row && row.enabled) {
235	    subject = row.subject;
236	    body = row.html;
237	  } else {
238	    const d = DEFAULTS[key] ?? GENERIC_FALLBACK(key);
