// ---- Transactional templates ----
//
// The full transactional catalog lives in `lib/email-templates.ts` (30+
// templates, all composed from the shared inline-styled components). It is
// re-exported here as `emails` so every existing call site — `import { emails }
// from "@/lib/mailer"` — keeps working unchanged. Each entry returns
// `{ template, subject, html }`; the six original signatures are preserved.
export type { BuiltEmail };

// ===========================================================================
// Card billing & dunning templates
//
// Renewals apply wallet credit first, then auto-charge the customer's saved
// card for the remainder. When that charge fails we retry on day 1, 3 and 5 and
// only suspend once the retries are exhausted. These templates carry that flow.
//
// They live here rather than in `lib/email-templates.ts` only because this file
// is the one owned by the card-billing change; they are built with the same
// `build()` shape and the same shared components, so they render identically to
// the rest of the catalog.
// ===========================================================================

/**
 * Number of automatic retries in the dunning sequence (day 1, day 3, day 5).
 * `paymentRetryFailed` uses it to tell the customer how many attempts are left,
 * so the worker's retry schedule and this copy must agree.
 */
export const DUNNING_RETRY_ATTEMPTS = 3;

/**
 * Same composition helper as `lib/email-templates.ts` (which keeps its copy
 * module-private): eyebrow → heading → body blocks → single CTA → optional
 * footnote, wrapped with a preheader by the shared shell.
 */
function build(opts: {
  template: string;
  subject: string;
  preheader: string;
  eyebrow?: string;
  accent?: Accent;
  heading: string;
  blocks: string[];
  cta?: { href: string; label: string; accent?: Accent };
  note?: string;
}): BuiltEmail {
  const parts: string[] = [];
  if (opts.eyebrow) parts.push(emailEyebrow(opts.eyebrow, opts.accent ?? "violet"));
  parts.push(emailHeading(opts.heading));
  parts.push(...opts.blocks);
  if (opts.cta) parts.push(emailButton(opts.cta.href, opts.cta.label, opts.cta.accent ?? "violet"));
  if (opts.note) parts.push(emailNote(opts.note));
  return {
    template: opts.template,
    subject: opts.subject,
    html: wrapEmail(parts.join("\n"), { preheader: opts.preheader }),
  };
}

/** Masked card display used wherever we echo the saved card back. */
const cardLabel = (last4: string) => `&bull;&bull;&bull;&bull;&nbsp;${last4}`;

/** `MM/YYYY` from the raw Stripe expiry fields — never guessed, only formatted. */
const expiryLabel = (expMonth: number, expYear: number) => `${String(expMonth).padStart(2, "0")}/${expYear}`;

/** Reassurance line reused across the dunning sequence. Nothing is suspended yet. */
const stillRunning = (hostname: string, extra = "") =>
  emailBanner(`<b>${hostname}</b> is still running. Nothing has been suspended.${extra ? ` ${extra}` : ""}`, "success");

const legacyPaymentFailed = catalogEmails.paymentFailed;
type LegacyPaymentFailedArgs = Parameters<typeof legacyPaymentFailed>[0];

/**
 * Card charge declined — FIRST failure of the dunning sequence.
 *
 * Overloaded so the original catalog shape (`{ amount, reason, updateUrl? }`,
 * still used by the admin template previewer) keeps working alongside the new
 * renewal-dunning shape.
 */
function paymentFailed(a: LegacyPaymentFailedArgs): BuiltEmail;
function paymentFailed(
  hostname: string,
  amountFormatted: string,
  last4: string,
  retryDateFormatted: string,
  billingUrl: string,
): BuiltEmail;
function paymentFailed(
  a: string | LegacyPaymentFailedArgs,
  amountFormatted?: string,
  last4?: string,
  retryDateFormatted?: string,
  billingUrl?: string,
): BuiltEmail {
  if (typeof a !== "string") return legacyPaymentFailed(a);
  const hostname = a;
  const amount = amountFormatted ?? "";
  const card = last4 ?? "";
  const retryDate = retryDateFormatted ?? "";
  const href = billingUrl ?? `${appUrl()}/dashboard/billing`;
  return build({
    template: "payment_failed",
    subject: `Card declined for ${hostname} — we'll retry ${retryDate}`,
    preheader: `${hostname} is still running. We'll try the card again on ${retryDate}.`,
    eyebrow: "Payment issue",
    accent: "warn",
    heading: "We couldn't charge your card",
    blocks: [
      emailParagraph(
        `The renewal payment for <b>${hostname}</b> didn't go through. Declines are usually something on the bank's side — a routine fraud check, a spending limit, or a card that's been reissued — so this often isn't anything you did.`,
      ),
      stillRunning(hostname),
      emailPanel(
        emailKeyValue([
          ["Server", hostname],
          ["Amount due", amount],
          ["Card", cardLabel(card)],
          ["Next attempt", retryDate],
        ]),
        "warn",
      ),
      emailParagraph(
        `We'll try the same card again on <b>${retryDate}</b>. If you'd rather not wait, update your card and we'll charge it straight away.`,
      ),
    ],
    cta: { href, label: "Update payment method", accent: "warn" },
    note: `If your bank asked you to approve the charge, approving it is enough. Anything else — just reply to this email and our team will take a look.`,
  });
}

const billingEmails = {
  /** Successful auto-charge against the saved card. */
  paymentReceipt: (amountFormatted: string, description: string, last4: string): BuiltEmail =>
    build({
      template: "payment_receipt",
      subject: `Receipt for ${amountFormatted} — card ending ${last4}`,
      preheader: `We charged ${amountFormatted} to your saved card. Everything is running as normal.`,
      eyebrow: "Receipt",
      accent: "success",
      heading: "Payment received",
      blocks: [
        emailParagraph(
          "Your renewal has been paid automatically using the card saved on your account. Everything is running as normal — there's nothing you need to do.",
        ),
        emailPanel(
          emailKeyValue([
            ["Amount", `<span style="color:#15a34a;">${amountFormatted}</span>`],
            ["For", description],
            ["Card", cardLabel(last4)],
          ]),
          "success",
        ),
        emailParagraph("Any wallet credit on your account was applied first; the amount above is what we charged to the card."),
      ],
      cta: { href: `${appUrl()}/dashboard/invoices`, label: "View invoices" },
      note: "Keep this email for your records, or download the itemised invoice from your dashboard at any time.",
    }),

  /** First declined charge in the dunning sequence (see the overloads above). */
  paymentFailed,

  /** A later retry in the dunning sequence was declined. */
  paymentRetryFailed: (
    hostname: string,
    amountFormatted: string,
    attempt: number,
    finalDateFormatted: string,
    billingUrl: string,
  ): BuiltEmail => {
    const remaining = Math.max(0, DUNNING_RETRY_ATTEMPTS - attempt);
    const remainingLine =
      remaining > 0
        ? `We'll try ${remaining} more time${remaining === 1 ? "" : "s"} before then.`
        : "That was the last automatic attempt.";
    return build({
      template: "payment_retry_failed",
      subject: `Payment retry ${attempt} declined for ${hostname} — still running until ${finalDateFormatted}`,
      preheader: `${hostname} stays online until ${finalDateFormatted}. ${remainingLine}`,
      eyebrow: `Retry ${attempt} declined`,
      accent: "warn",
      heading: "Your card was declined again",
      blocks: [
        emailParagraph(
          `We tried the saved card for <b>${hostname}</b> again and it was declined. If the card is fine on your end, it's worth asking your bank whether they're blocking the charge — that's the usual cause at this stage.`,
        ),
        stillRunning(hostname, `It stays online until <b>${finalDateFormatted}</b>.`),
        emailPanel(
          emailKeyValue([
            ["Server", hostname],
            ["Amount due", amountFormatted],
            ["Attempt", String(attempt)],
            ["Attempts remaining", String(remaining)],
            ["Suspends on", finalDateFormatted],
          ]),
          "warn",
        ),
        emailParagraph(
          `${remainingLine} If the balance is still unpaid on <b>${finalDateFormatted}</b>, <b>${hostname}</b> will be suspended — your data stays intact and paying restores it.`,
        ),
        emailParagraph("Updating your card now settles the balance immediately and stops the remaining retries."),
      ],
      cta: { href: billingUrl, label: "Update payment method", accent: "warn" },
      note: "If something about this charge looks wrong, or you need a little more time, reply to this email — we'd rather work it out with you.",
    });
  },

  /** Stripe returned `requires_action` — the customer must complete 3-D Secure. */
  paymentActionRequired: (hostname: string, amountFormatted: string, authUrl: string): BuiltEmail =>
    build({
      template: "payment_action_required",
      subject: `Confirm the ${amountFormatted} payment for ${hostname} with your bank`,
      preheader: `${hostname} is still running. Your bank needs one quick confirmation to finish the payment.`,
      eyebrow: "Confirmation needed",
      accent: "info",
      heading: "Your bank needs to confirm this payment",
      blocks: [
        emailParagraph(
          `Your card issuer asked for an extra verification step before the renewal payment for <b>${hostname}</b> can complete. This is a routine security check on their side, and it takes less than a minute.`,
        ),
        stillRunning(hostname, "Confirming the payment keeps it that way."),
        emailPanel(
          emailKeyValue([
            ["Server", hostname],
            ["Amount", amountFormatted],
            ["Waiting on", "Bank confirmation (3-D Secure)"],
          ]),
        ),
        emailParagraph("Use the button below to confirm with your bank. We'll finish the payment as soon as they approve it."),
      ],
      cta: { href: authUrl, label: "Confirm payment with your bank" },
      note: `This confirmation link is unique to this payment and expires after a short while. If it's already expired, open <a href="${appUrl()}/dashboard/billing" style="color:#6f47f5;">Billing</a> and we'll start a fresh attempt.`,
    }),

  /** Final retry failed — the last warning before the server is suspended. */
  paymentFinalNotice: (hostname: string, amountFormatted: string, billingUrl: string): BuiltEmail =>
    build({
      template: "payment_final_notice",
      subject: `Final notice for ${hostname} — ${amountFormatted} still unpaid`,
      preheader: `${hostname} is still running, but this is the last notice before it's suspended.`,
      eyebrow: "Final notice",
      accent: "danger",
      heading: "Last notice before suspension",
      blocks: [
        emailParagraph(
          `We've now tried the saved card for <b>${hostname}</b> as many times as we can, and it's still being declined. We've run out of automatic attempts, so this is the last message before the server has to be paused.`,
        ),
        stillRunning(hostname, `Paying the outstanding <b>${amountFormatted}</b> keeps it online.`),
        emailPanel(
          emailKeyValue([
            ["Server", hostname],
            ["Outstanding", amountFormatted],
            ["Status", "Running — awaiting payment"],
          ]),
          "danger",
        ),
        emailParagraph(
          "If the server is suspended it stops serving traffic, but nothing is deleted — your data and configuration stay exactly as they are, and settling the balance brings it straight back.",
        ),
        emailParagraph("Paying now, or switching to a different card, avoids the suspension entirely."),
      ],
      cta: { href: billingUrl, label: "Settle the balance", accent: "danger" },
      note: "If the charge looks wrong, or you need a few more days, reply to this email before the suspension date — we'd much rather sort it out with you than pause anything.",
    }),

  /** Proactive heads-up that the card saved for auto-renewal is about to expire. */
  cardExpiringSoon: (last4: string, expMonth: number, expYear: number, billingUrl: string): BuiltEmail =>
    build({
      template: "card_expiring_soon",
      subject: `Your card ending ${last4} expires ${expiryLabel(expMonth, expYear)}`,
      preheader: `Nothing is wrong today — just a heads-up so your next renewal goes through.`,
      eyebrow: "Card expiring",
      accent: "warn",
      heading: "Your saved card expires soon",
      blocks: [
        emailParagraph(
          `The card we use for automatic renewals expires on <b>${expiryLabel(expMonth, expYear)}</b>. Saving an up-to-date card now means your next renewal goes through without anyone having to think about it.`,
        ),
        emailBanner("All of your services are running normally. There's nothing wrong with your account today.", "success"),
        emailPanel(
          emailKeyValue([
            ["Card", cardLabel(last4)],
            ["Expires", expiryLabel(expMonth, expYear)],
          ]),
          "warn",
        ),
        emailParagraph(
          "If your bank has already sent a replacement, adding it takes about a minute. If the card has been renewed with the same number, just update the expiry date.",
        ),
      ],
      cta: { href: billingUrl, label: "Update card", accent: "warn" },
      note: "We only charge the card for renewals you've already agreed to, and only for the amount your wallet credit doesn't cover.",
    }),
};

/**
 * The complete catalog: everything from `lib/email-templates.ts` plus the card
 * billing / dunning templates above. Exported under the same name so every
 * `import { emails } from "@/lib/mailer"` call site keeps working unchanged.
 */
export const emails = { ...catalogEmails, ...billingEmails };
export type EmailKey = keyof typeof emails;

// Re-exported so other modules can build DB-templated bodies consistently.
export { wrapEmail, emailButton };

